    {loading ? loadingView() : error ? <div className=\"chart-state\" role=\"alert\"><Text>{error}</Text>{onRetry && <Button onClick={onRetry}>Повторить</Button>}</div> : "'!series.length || !series.some(s => s.data.length) ? <div className="chart-state"><Text color="secondary">Нет данных для отображения</Text><Text variant="caption-2" color="hint">Выберите хотя бы одну серию или другой период</Text></div> : mode === '"'sales' ?
